#!/usr/bin/env bash
# Write the Info.plist keys Apple requires into the generated iOS project.
#
# ios/ is gitignored - it is regenerated by `npx cap add ios` on every build -
# so none of this can simply live in the repo. It has to be applied after
# `cap sync` and before `xcodebuild`, which is what both CI configs do.
#
# Capacitor has no config option for arbitrary Info.plist keys, hence
# PlistBuddy. Run from the repo root.
set -euo pipefail

PLIST="${1:-ios/App/App/Info.plist}"

if [ ! -f "$PLIST" ]; then
  echo "No Info.plist at $PLIST - run 'npx cap add ios' first." >&2
  exit 1
fi

plist() { /usr/libexec/PlistBuddy -c "$1" "$PLIST"; }

set_bool() {
  plist "Add :$1 bool $2" 2>/dev/null || plist "Set :$1 $2"
}

set_string() {
  plist "Add :$1 string $2" 2>/dev/null || plist "Set :$1 $2"
}

# Export compliance. Bible Buddy only talks HTTPS, which is the encryption
# Apple's own OS provides and is exempt. Without this key every upload stops
# and asks the question by hand, which is a step that gets forgotten at 2am.
set_bool ITSAppUsesNonExemptEncryption false

# Permission prompts. Apple rejects vague wording, and a *missing* string is
# worse than a bad one - iOS kills the app the moment the webview asks.
set_string NSMicrophoneUsageDescription \
  "Bible Buddy uses the microphone so you can speak to Little Louis instead of typing."
set_string NSPhotoLibraryUsageDescription \
  "Bible Buddy needs access to your photos so you can set a profile picture and share images in your study group."
set_string NSCameraUsageDescription \
  "Bible Buddy uses the camera so you can take a photo for your profile or your study group."

# Chapter audio and the Bible-in-One-Year readings have to keep playing when
# the screen locks. Without this the lock-screen controls in lib/mediaSession.ts
# appear and then go silent, which is worse than not having them.
if ! plist "Print :UIBackgroundModes" >/dev/null 2>&1; then
  plist "Add :UIBackgroundModes array"
fi
if ! plist "Print :UIBackgroundModes" | grep -q "audio"; then
  plist "Add :UIBackgroundModes: string audio"
fi

echo "--- Info.plist ---"
plist "Print"
